"""Receiver tests use generated bytes/processes only, never a camera or private session."""
import importlib.util
import json
import os
from pathlib import Path
import shutil
import signal
import subprocess
import sys
import tempfile
import threading
import time
import unittest
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[1]
COLLECTOR = ROOT / 'video' / 'collector.py'
SCRATCH = ROOT / 'private' / 'video-receiver-validation'


class CollectorTests(unittest.TestCase):
    def setUp(self):
        self.assertTrue(COLLECTOR.is_file(), 'bounded collector not implemented')
        spec = importlib.util.spec_from_file_location('video_collector', COLLECTOR)
        self.collector = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(self.collector)
        SCRATCH.mkdir(parents=True, exist_ok=True)
        self.temp = tempfile.TemporaryDirectory(dir=SCRATCH)
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.archive = self.root / 'recordings'
        self.archive.mkdir()
        self.probe = self.root / 'probe.py'
        self.probe.write_text('import json; print(json.dumps({"format":{"duration":"1.5"},"streams":[{"codec_type":"video","width":64,"height":48,"avg_frame_rate":"20/1","r_frame_rate":"20/1"}]}))', encoding='utf-8')
        self.decoder = self.root / 'decoder.py'
        self.decoder.write_text('raise SystemExit(0)', encoding='utf-8')
        self.config = {'archiveRoot': str(self.archive), 'cameraId': 'camera-test',
            'stationId': 'station-test', 'mappingVersion': 'v1', 'timezone': 'UTC',
            'maxSeconds': 5, 'startupTimeoutSeconds': .3, 'stallTimeoutSeconds': .2,
            'totalTimeoutSeconds': 1, 'maxBytes': 65536, 'minFreeBytes': 0,
            'probeTimeoutSeconds': .5, 'ffmpeg': sys.executable, 'decodeTimeoutSeconds': .5}

    def collect(self, code, stop=None):
        source = self.root / 'source.py'
        source.write_text(code, encoding='utf-8')
        return self.collector._collect(self.config, [sys.executable, '-u', str(source)],
            [sys.executable, str(self.probe)], stop or threading.Event(),
            decode_prefix=[sys.executable, str(self.decoder)])

    def assert_unregistered(self):
        self.assertEqual(list(self.archive.glob('*/capture.json')), [])
        self.assertEqual(list(self.archive.glob('*/video.mp4')), [])
        self.assertEqual(list(self.archive.glob('*/video.mp4.part')), [])

    def test_completed_finite_source_registers_hash_and_estimated_partial_timeline(self):
        capture = self.collect('import sys; sys.stdout.buffer.write(b"synthetic-mp4"); sys.stdout.flush()')
        recording = capture['recording']
        self.assertEqual(capture['status'], 'complete')
        self.assertEqual(capture['coverage']['status'], 'partial')
        self.assertEqual(recording['timing'], 'estimated')
        self.assertEqual(recording['durationSeconds'], 1.5)
        self.assertEqual(capture['cameraId'], 'camera-test')
        self.assertEqual(capture['timingSource'], 'bridge-genpts-20fps')
        self.assertEqual(len(recording['sha256']), 64)
        self.assertLessEqual(capture['receivingStartedAt'], recording['startedAt'])
        self.assertLessEqual(recording['startedAt'], capture['receivingEndedAt'])
        run = self.archive / capture['runId']
        self.assertEqual(json.loads((run / 'capture.json').read_text()), capture)
        self.assertEqual((self.archive / recording['file']).read_bytes(), b'synthetic-mp4')
        self.assertFalse((run / 'video.mp4.part').exists())

    def test_no_first_byte_expires_without_manifest(self):
        with self.assertRaisesRegex(self.collector.CaptureError, 'START_TIMEOUT'):
            self.collect('import time; time.sleep(30)')
        self.assert_unregistered()

    def test_stalled_source_expires_without_manifest(self):
        with self.assertRaisesRegex(self.collector.CaptureError, 'STALL_TIMEOUT'):
            self.collect('import sys,time; sys.stdout.buffer.write(b"x");sys.stdout.flush();time.sleep(30)')
        self.assert_unregistered()

    def test_total_limit_stops_a_source_that_keeps_making_progress(self):
        self.config['totalTimeoutSeconds'] = .3
        with self.assertRaisesRegex(self.collector.CaptureError, 'TOTAL_TIMEOUT'):
            self.collect('import sys,time\nwhile True:\n sys.stdout.buffer.write(b"x");sys.stdout.flush();time.sleep(.02)')
        self.assert_unregistered()

    def test_byte_limit_does_not_register_partial_video(self):
        self.config['maxBytes'] = 10
        with self.assertRaisesRegex(self.collector.CaptureError, 'BYTE_LIMIT'):
            self.collect('import sys;sys.stdout.buffer.write(b"x"*5000);sys.stdout.flush()')
        self.assert_unregistered()

    def test_free_space_checked_before_start_and_during_capture(self):
        usage = self.collector.shutil.disk_usage(self.archive)
        self.config['minFreeBytes'] = usage.free + 1
        with self.assertRaisesRegex(self.collector.CaptureError, 'DISK_LIMIT'):
            self.collect('raise AssertionError("should not start")')
        self.assert_unregistered()
        self.config['minFreeBytes'] = 1
        with patch.object(self.collector.shutil, 'disk_usage', side_effect=[usage, (0, 0, 0)]):
            with self.assertRaisesRegex(self.collector.CaptureError, 'DISK_LIMIT'):
                self.collect('import sys;sys.stdout.buffer.write(b"x");sys.stdout.flush()')
        self.assert_unregistered()

    def test_nonzero_source_and_empty_source_not_registered(self):
        for code, error in [('import sys;sys.stdout.buffer.write(b"x");sys.exit(4)', 'SOURCE_FAILED'), ('pass', 'EMPTY_CAPTURE')]:
            with self.subTest(error=error):
                with self.assertRaisesRegex(self.collector.CaptureError, error):
                    self.collect(code)
                self.assert_unregistered()

    def test_invalid_and_overlong_probe_results_not_registered(self):
        for result in ['not-json', '{"format":{"duration":"0"},"streams":[]}', '{"format":{"duration":"9000"},"streams":[{"codec_type":"video","width":4,"height":4}]}']:
            self.probe.write_text('print(' + repr(result) + ')', encoding='utf-8')
            with self.assertRaisesRegex(self.collector.CaptureError, 'INVALID_VIDEO'):
                self.collect('import sys;sys.stdout.buffer.write(b"x")')
            self.assert_unregistered()

    def test_probe_error_and_timeout_do_not_register(self):
        for code, error in [('raise SystemExit(1)', 'INVALID_VIDEO'), ('import time;time.sleep(30)', 'PROBE_TIMEOUT')]:
            self.probe.write_text(code, encoding='utf-8')
            with self.assertRaisesRegex(self.collector.CaptureError, error):
                self.collect('import sys;sys.stdout.buffer.write(b"x")')
            self.assert_unregistered()

    def test_decode_failure_does_not_register_even_when_headers_are_valid(self):
        self.decoder.write_text('raise SystemExit(1)', encoding='utf-8')
        with self.assertRaisesRegex(self.collector.CaptureError, 'INVALID_VIDEO'):
            self.collect('import sys;sys.stdout.buffer.write(b"headers-valid-but-truncated")')
        self.assert_unregistered()

    def test_decode_timeout_does_not_register_and_reaps_decoder(self):
        self.decoder.write_text('import time;time.sleep(30)', encoding='utf-8')
        launched = []
        start = self.collector._start

        def record_start(argv):
            process = start(argv)
            launched.append(process)
            return process

        with patch.object(self.collector, '_start', side_effect=record_start):
            with self.assertRaisesRegex(self.collector.CaptureError, 'DECODE_TIMEOUT'):
                self.collect('import sys;sys.stdout.buffer.write(b"x")')
        self.assertEqual(len(launched), 3)
        self.assertTrue(all(process.poll() is not None for process in launched))
        self.assert_unregistered()

    def test_stop_during_decode_does_not_register(self):
        marker = self.root / 'decoder.started'
        self.decoder.write_text('from pathlib import Path;import time;Path(' + repr(str(marker)) + ').write_text("started");time.sleep(30)', encoding='utf-8')
        stop = threading.Event()

        def cancel_after_decode_starts():
            deadline = time.monotonic() + 2
            while not marker.exists() and time.monotonic() < deadline:
                time.sleep(.01)
            if marker.exists():
                stop.set()

        watcher = threading.Thread(target=cancel_after_decode_starts, daemon=True)
        watcher.start()
        with self.assertRaisesRegex(self.collector.CaptureError, 'STOPPED'):
            self.collect('import sys;sys.stdout.buffer.write(b"x")', stop)
        watcher.join(timeout=2)
        self.assertTrue(marker.exists())
        self.assert_unregistered()

    def test_probe_enforces_analyzer_resolution_and_frame_rate_budget(self):
        for width, height, fps in [(3841, 2160, '20/1'), (3840, 2161, '20/1'), (3840, 2160, '121/1')]:
            result = {'format': {'duration': '1.5'}, 'streams': [{'codec_type': 'video',
                'width': width, 'height': height, 'avg_frame_rate': fps, 'r_frame_rate': fps}]}
            self.probe.write_text('print(' + repr(json.dumps(result)) + ')', encoding='utf-8')
            with self.assertRaisesRegex(self.collector.CaptureError, 'INVALID_VIDEO'):
                self.collect('import sys;sys.stdout.buffer.write(b"x")')
            self.assert_unregistered()

    @unittest.skipUnless(shutil.which('ffmpeg') and shutil.which('ffprobe'), 'optional real FFmpeg integration')
    def test_real_fmp4_with_truncated_tail_rejected_but_complete_file_accepted(self):
        ffmpeg, ffprobe = shutil.which('ffmpeg'), shutil.which('ffprobe')
        valid = self.root / 'generated.mp4'
        subprocess.run([ffmpeg, '-hide_banner', '-loglevel', 'error', '-nostdin',
            '-f', 'lavfi', '-i', 'testsrc2=s=160x120:r=20', '-t', '3', '-an',
            '-c:v', 'libx264', '-preset', 'ultrafast', '-pix_fmt', 'yuv420p', '-g', '20',
            '-movflags', 'frag_keyframe+empty_moov+default_base_moof', '-f', 'mp4', str(valid)],
            check=True, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=10)
        broken = self.root / 'truncated.mp4'
        broken.write_bytes(valid.read_bytes()[:-128])
        # The regression specifically requires a broken file that still passes
        # header probing, so a failure cannot be mistaken for existing validation.
        metadata = subprocess.run([ffprobe, '-v', 'error', '-show_entries',
            'format=duration:stream=codec_type', '-of', 'json', str(broken)],
            stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=5)
        self.assertEqual(metadata.returncode, 0)
        self.assertGreater(float(json.loads(metadata.stdout)['format']['duration']), 0)
        self.config.update(ffmpeg=ffmpeg, maxBytes=1024 * 1024, startupTimeoutSeconds=2,
            totalTimeoutSeconds=5, probeTimeoutSeconds=3, decodeTimeoutSeconds=5)
        source = self.root / 'file-source.py'
        source.write_text('import sys;from pathlib import Path;sys.stdout.buffer.write(Path(sys.argv[1]).read_bytes())', encoding='utf-8')
        with self.assertRaisesRegex(self.collector.CaptureError, 'INVALID_VIDEO'):
            self.collector._collect(self.config, [sys.executable, str(source), str(broken)], [ffprobe], threading.Event())
        self.assert_unregistered()
        capture = self.collector._collect(self.config, [sys.executable, str(source), str(valid)], [ffprobe], threading.Event())
        self.assertEqual(capture['status'], 'complete')

    def test_stop_event_reaps_source_without_registration(self):
        stop = threading.Event()
        timer = threading.Timer(.1, stop.set)
        timer.start()
        self.addCleanup(timer.cancel)
        with self.assertRaisesRegex(self.collector.CaptureError, 'STOPPED'):
            self.collect('import time;time.sleep(30)', stop)
        self.assert_unregistered()

    def test_only_fixed_bridge_command_and_private_config_accepted(self):
        bridge = self.root / 'bridge.json'
        bridge.write_text('{"maxSeconds":5}')
        config = dict(self.config, pythonExecutable=sys.executable, ffprobe=sys.executable,
            bridgeConfig=str(bridge), maxBytes=1000000, minFreeBytes=0,
            startupTimeoutSeconds=2, stallTimeoutSeconds=2, totalTimeoutSeconds=10,
            probeTimeoutSeconds=2, decodeTimeoutSeconds=2)
        file = self.root / 'collector.json'
        file.write_text(json.dumps(config))
        loaded = self.collector.load_config(file)
        argv = self.collector.bridge_arguments(loaded)
        self.assertEqual(argv, [str(Path(sys.executable).resolve()), '-u', str(ROOT / 'tools' / 'xiaomi_live_bridge.py'), '--config', str(bridge.resolve())])
        config['command'] = 'echo secret'
        file.write_text(json.dumps(config))
        with self.assertRaisesRegex(self.collector.CaptureError, 'INVALID_CONFIG'):
            self.collector.load_config(file)
        del config['command']
        file.write_text(json.dumps(config))
        bridge.write_text('{"maxSeconds":600}')
        with self.assertRaisesRegex(self.collector.CaptureError, 'INVALID_BRIDGE_DURATION'):
            self.collector.load_config(file)

    def test_decoder_dependency_and_timeout_limit_cannot_be_omitted_or_unbounded(self):
        bridge = self.root / 'bridge.json'
        bridge.write_text('{"maxSeconds":5}')
        config = dict(self.config, pythonExecutable=sys.executable, ffprobe=sys.executable,
            bridgeConfig=str(bridge), maxBytes=1000000, startupTimeoutSeconds=2,
            stallTimeoutSeconds=2, totalTimeoutSeconds=10, probeTimeoutSeconds=2)
        file = self.root / 'collector.json'
        del config['ffmpeg']
        file.write_text(json.dumps(config))
        with self.assertRaisesRegex(self.collector.CaptureError, 'INVALID_CONFIG'):
            self.collector.load_config(file)
        config['ffmpeg'] = sys.executable
        for timeout in [0, 601, True, .5]:
            config['decodeTimeoutSeconds'] = timeout
            file.write_text(json.dumps(config))
            with self.assertRaisesRegex(self.collector.CaptureError, 'INVALID_LIMIT'):
                self.collector.load_config(file)

    def test_preflight_fails_cleanly_without_supplied_vendor_and_no_upstream_output(self):
        process = subprocess.run([sys.executable, str(ROOT / 'deploy' / 'video-preflight.py'),
            '--bridge-config', str(self.root / 'never-read.json'),
            '--vendor-classes', str(self.root / 'missing-vendor')], capture_output=True, timeout=3)
        self.assertEqual(process.returncode, 2)
        self.assertEqual(process.stdout, b'')
        self.assertEqual(process.stderr.strip(), b'VENDOR_CLASSES_MISSING')

    @unittest.skipUnless(os.name == 'posix', 'POSIX signal/process-group assertion; Windows uses bounded taskkill')
    def test_sigterm_cleans_descendant_even_if_parent_already_exited(self):
        pidfile = self.root / 'descendant.pid'
        source = self.root / 'tree.py'
        source.write_text('import subprocess,sys\np=subprocess.Popen([sys.executable,"-c","import time;time.sleep(30)"])\nopen(sys.argv[1],"w").write(str(p.pid))\nsys.stdout.buffer.write(b"x");sys.stdout.flush()\n', encoding='utf-8')
        wrapper = self.root / 'wrapper.py'
        wrapper.write_text('import importlib.util,signal,threading,sys\nspec=importlib.util.spec_from_file_location("collector",sys.argv[1]);c=importlib.util.module_from_spec(spec);spec.loader.exec_module(c)\nstop=threading.Event();signal.signal(signal.SIGTERM,lambda *_:stop.set())\nimport json\ntry:c._collect(json.loads(sys.argv[2]),[sys.executable,"-u",sys.argv[3],sys.argv[4]],[sys.executable,sys.argv[5]],stop)\nexcept c.CaptureError:raise SystemExit(2)\n', encoding='utf-8')
        process = subprocess.Popen([sys.executable, str(wrapper), str(COLLECTOR), json.dumps(self.config), str(source), str(pidfile), str(self.probe)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        self.addCleanup(lambda: process.kill() if process.poll() is None else None)
        deadline = time.monotonic() + 3
        while not pidfile.exists() and time.monotonic() < deadline:
            time.sleep(.02)
        self.assertTrue(pidfile.exists())
        pid = int(pidfile.read_text())
        process.send_signal(signal.SIGTERM)
        self.assertEqual(process.wait(timeout=5), 2)
        deadline = time.monotonic() + 2
        while time.monotonic() < deadline:
            try:
                state = Path(f'/proc/{pid}/stat').read_text().split()[2]
                if state == 'Z':
                    break  # Terminated, awaiting init's reap inside CI.
            except FileNotFoundError:
                break
            time.sleep(.02)
        else:
            self.fail('descendant remains running')
        self.assert_unregistered()


if __name__ == '__main__':
    unittest.main()
